        // Research
        ["Portfolio.But.Year3.Research.Title"] = "Computer science research",
        ["Portfolio.But.Year3.Research.Intro"] = "Through introductory research workshops, I explored the foundations of scientific methodology in computer science: distinguishing fundamental vs. applied research, defining hypotheses, designing experiments, and documenting protocols to ensure results are verifiable and reproducible.",
        ["Portfolio.But.Year3.Research.Workshop.Title"] = "Experimental workshop — Eye‑tracking (20–30 min)",
        ["Portfolio.But.Year3.Research.Workshop.Content"] = "As an observed participant, I took part in an eye‑tracking experiment aimed at comparing beginners’ and experts’ visual strategies while analyzing different climbing walls, in order to identify differences in gaze patterns and attention.",
        ["Portfolio.But.Year3.Research.Course.Title"] = "Lecture — Research overview (1h30)",
        ["Portfolio.But.Year3.Research.Course.Content"] = "A lecture titled “Computer Science Research” introduced the main concepts and methods of research, and how research is organized in France, including public university laboratories. Two educational research examples illustrated these ideas:",
        ["Portfolio.But.Year3.Research.Course.List1"] = "a roguelike video game designed to help learners practice multiplication tables;",
        ["Portfolio.But.Year3.Research.Course.List2"] = "an application for building educational routes/itineraries (museum visits, school trips, etc.).",
        ["Portfolio.But.Year3.Research.Takeaways.Title"] = "Key takeaways",
        ["Portfolio.But.Year3.Research.Takeaways.Item1.Strong"] = "Fundamental vs. applied research:",
        ["Portfolio.But.Year3.Research.Takeaways.Item1.Text"] = "understanding/theory vs. practical, measurable solutions.",
        ["Portfolio.But.Year3.Research.Takeaways.Item2.Strong"] = "Reproducibility:",
        ["Portfolio.But.Year3.Research.Takeaways.Item2.Text"] = "experiments should be repeatable “like a recipe” through clear documentation.",
        ["Portfolio.But.Year3.Research.Takeaways.Item3.Strong"] = "Rigor:",
        ["Portfolio.But.Year3.Research.Takeaways.Item3.Text"] = "strict methodology is challenging but essential for reliable outcomes.",
        ["Portfolio.But.Year3.Research.Takeaways.Item4.Strong"] = "Collaboration:",
        ["Portfolio.But.Year3.Research.Takeaways.Item4.Text"] = "working with domain experts (educators, specialists) is highly valuable.",
        ["Portfolio.But.Year3.Research.Takeaways.Item5.Strong"] = "Constraints:",
        ["Portfolio.But.Year3.Research.Takeaways.Item5.Text"] = "funding is a key challenge in research projects.",
        ["Portfolio.But.Year3.Research.Opinion.Title"] = "Personal perspective",
        ["Portfolio.But.Year3.Research.Opinion.Content"] = "My primary goal is to work as a software developer. I’m curious about research, even if I don’t plan to pursue it as a career. However, the workshops strengthened habits that directly apply to software engineering: rigor, traceability, and quality-focused practices (documentation, repeatable debugging and testing).",
        ["Portfolio.But.Year3.Research.MindMap.Title"] = "Infographic: Scientific method",
        ["Portfolio.But.Year3.Research.MindMap.Path"] = "images/portfolio/BUTInfo/Year3/MindMap_en.png",
        ["Portfolio.But.Year3.Research.MindMap.Alt"] = "Research mind map",

