        ["Portfolio.BeyondAcademics.Culture.Year3.Title"] = "Year 3",
        ["Portfolio.BeyondAcademics.Culture.Year3.Period"] = "2023 - 2024",
        ["Portfolio.BeyondAcademics.Culture.Year3.Content"] = "Description of cultural enrichment in the third year.",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Title"] = "Semester 5 & 6",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Objectives.Title"] = "Personal objectives",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Objectives.P1"] = "As part of developing my general knowledge and cross-functional skills, I set myself three main objectives for semester 5:",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Objectives.L1"] = "Read and analyze a major scientific work: <em>On the Origin of Species</em> by Charles Darwin.",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Objectives.L2"] = "Develop a reflection on the ethical issues of digital technology.",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Objectives.L3"] = "Improve my academic French skills with the ECRI+ certification.",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Objectives.P2"] = "These objectives were chosen to develop complementary skills:",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Objectives.C1"] = "intellectual and scientific analysis",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Objectives.C2"] = "understanding societal issues related to digital technology",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Objectives.C3"] = "ability to evolve in an international environment",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Objectives.P3"] = "They directly contribute to my preparation for <strong>employee status in the IT sector</strong>, where the ability to understand complex systems, reflect on the impact of technologies, and communicate effectively is essential.",

        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj1.Title"] = "Objective 1: Reading and analyzing a major scientific work",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj1.Sub1"] = "Studied work",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj1.Book"] = "<em>On the Origin of Species</em> – Charles Darwin",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj1.Sub2"] = "Why this objective",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj1.Why.P1"] = "I chose to read this work because it is a foundational text of modern scientific thought. In this book published in 1859, Charles Darwin outlines the theory of <strong>natural selection</strong>, which explains the evolution of species through a process of variation, heredity, and competition for resources.",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj1.Why.P2"] = "Reading this book helped me better understand how a scientific theory is built: Darwin develops progressive reasoning based on empirical observations, comparisons between species, and rigorous argumentation.",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj1.Why.P3"] = "Beyond biology, this reading led me to reflect on the notion of an <strong>adaptive system</strong>, where simple rules can produce complex behaviors. This type of reasoning is particularly interesting in computer science, especially in the fields of <strong>evolutionary algorithms, optimization, and artificial intelligence</strong>.",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj1.Sub3"] = "Work completed",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj1.Work.P1"] = "During my reading, I produced a synthesis and reflection around several key chapters:",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj1.Work.L1"] = "<strong>Chapter 1: Variation under Domestication</strong> – studying the role of artificial selection in breeding and agriculture",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj1.Work.L2"] = "<strong>Chapter 3: Struggle for Existence</strong> – understanding competition for resources",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj1.Work.L3"] = "<strong>Chapter 4: Natural Selection</strong> – the central mechanism explaining species adaptation",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj1.Work.P2"] = "These chapters helped me understand the structure of Darwin's scientific reasoning and draw parallels with optimization processes used in computer science.",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj1.Sub4"] = "Benefits for my professional future",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj1.App.P1"] = "This reading helped me develop:",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj1.App.L1"] = "an <strong>ability to analyze complex reasoning</strong>",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj1.App.L2"] = "a better understanding of <strong>the history of scientific ideas</strong>",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj1.App.L3"] = "a reflection on <strong>adaptation and optimization mechanisms</strong>",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj1.App.P2"] = "These skills are useful in a professional context where developers must regularly analyze complex systems, understand advanced technical concepts, and continue learning throughout their careers.",

        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj2.Title"] = "Objective 2: Ethics & digital technology",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj2.Obj"] = "<strong>Objective:</strong> Develop <strong>general knowledge about the ethical issues related to digital technologies</strong>, in order to better understand the social, legal, and environmental impacts of IT systems.",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj2.Sub1"] = "Research areas",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj2.Axes.P1"] = "To achieve this objective, I studied three major themes:",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj2.Axes.T1"] = "1. Bias and artificial intelligence",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj2.Axes.A1.P1"] = "My research focused on how artificial intelligence systems can reproduce or amplify biases present in training data.",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj2.Axes.A1.P2"] = "In particular, I studied several examples documented in the scientific literature and specialized media, such as biases in facial recognition systems or recommendation algorithms.",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj2.Axes.A1.P3"] = "This work helped me understand the importance of:",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj2.Axes.A1.L1"] = "the <strong>quality of the data used to train models</strong>",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj2.Axes.A1.L2"] = "the <strong>transparency of algorithms</strong>",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj2.Axes.A1.L3"] = "the <strong>responsibility of developers when designing automated systems</strong>",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj2.Axes.T2"] = "2. Privacy and data protection (GDPR)",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj2.Axes.A2.P1"] = "I also studied the fundamental principles of the <strong>General Data Protection Regulation (GDPR)</strong> and their implications for software development. This includes:",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj2.Axes.A2.L1"] = "the <strong>minimization of collected data</strong>",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj2.Axes.A2.L2"] = "the <strong>security of personal information</strong>",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj2.Axes.A2.L3"] = "<strong>user consent</strong>",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj2.Axes.A2.P2"] = "This research helped me better understand the legal and ethical obligations associated with data processing in digital applications.",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj2.Axes.T3"] = "3. Environmental impact of digital technology",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj2.Axes.A3.P1"] = "Finally, I studied the ecological impact of digital technology, notably:",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj2.Axes.A3.L1"] = "the energy consumption of <strong>data centers</strong>",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj2.Axes.A3.L2"] = "the carbon footprint linked to digital infrastructures",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj2.Axes.A3.L3"] = "issues related to code optimization and the energy efficiency of software",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj2.Axes.A3.P2"] = "This reflection made me aware of the importance of designing more <strong>sober and efficient</strong> systems, in order to limit the environmental impact of digital technology.",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj2.App.Title"] = "Benefits for my professional future",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj2.App.P1"] = "This research helped me develop a more responsible approach to software development. As a future developer, it is important to:",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj2.App.L1"] = "understand the <strong>societal impacts of technologies</strong>",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj2.App.L2"] = "design systems that are <strong>respectful of users and their data</strong>",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj2.App.L3"] = "integrate <strong>ecological and ethical</strong> issues into technical choices",

        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj3.Title"] = "Objective 3: ECRI+",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj3.Obj1"] = "<strong>Objective:</strong> Improve my skills in understanding and analyzing argumentative texts in French through the <strong>ECRI+</strong> certification.",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj3.Obj2"] = "This certification assesses the ability to understand complex texts, identify an author's arguments, and analyze the structure of reasoning. It develops useful skills for critical reading and information analysis.",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj3.Sub1"] = "Progress",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj3.Prog.P1"] = "At the beginning of my preparation, my score was <strong>323 points</strong>. After regular work on the training exercises, I managed to reach <strong>600 points</strong>, which corresponds to <strong>level 4 in all the assessed skills</strong>.",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj3.Prog.P2"] = "This progress shows a significant improvement in my ability to:",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj3.Prog.L1"] = "understand <strong>complex argumentative texts</strong>",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj3.Prog.L2"] = "analyze the <strong>logical structure of reasoning</strong>",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj3.Prog.L3"] = "identify a text’s <strong>main ideas, examples, and conclusions</strong>",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj3.Sub2"] = "Work completed",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj3.Work.P1"] = "To improve my score, I completed many training exercises based on:",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj3.Work.L1"] = "the analysis of press articles and argumentative essays",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj3.Work.L2"] = "texts dealing with societal, scientific, and economic topics",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj3.Work.L3"] = "exercises on identifying arguments and the logical structure of a text",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj3.Work.P2"] = "This work helped me develop a more analytical and critical reading approach, learning to distinguish between facts, arguments, and examples in a text.",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj3.Sub3"] = "Benefits for my professional future",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj3.App.P1"] = "These skills are important in the professional world. They make it possible, in particular, to:",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj3.App.L1"] = "<strong>quickly understand</strong> working documents or reports",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj3.App.L2"] = "<strong>analyze complex problems</strong> and their different dimensions",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj3.App.L3"] = "<strong>structure clear argumentation</strong> in writing or speaking",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Obj3.App.P2"] = "ECRI+ therefore helped me strengthen my analytical, synthesis, and comprehension skills—essential qualities for evolving effectively in a professional environment.",

