        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Org.Cor.P1"] = "To adapt to academic constraints and other projects during the semester, I put in place a flexible organization:",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Org.Cor.L1"] = "spreading the reading over several weeks",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Org.Cor.L2"] = "progressive work on different themes in digital ethics",
