        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Org.Cor.P2"] = "This organization allowed me to maintain steady progress while balancing these objectives with my other responsibilities.",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Org.Sub3"] = "Review",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Org.Bil.P1"] = "These three objectives allowed me to broaden my general knowledge while developing useful skills for my professional future.",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Org.Bil.P2"] = "Reading a major scientific work gave me a better understanding of scientific reasoning and complex systems.<br />My research on digital ethics made me aware of the responsibilities associated with technological development.",
        ["Portfolio.BeyondAcademics.Culture.Year3.S5.Org.Bil.P3"] = "These learnings contribute to my development toward <strong>being an employee capable of continuous learning, critical thinking, and designing responsible technological solutions.</strong>",

        // Beyond Academics - Sport
        ["Portfolio.BeyondAcademics.Sport.Title"] = "Sports",
        ["Portfolio.BeyondAcademics.Sport.Subtitle"] = "My sports activities",
        ["Portfolio.BeyondAcademics.Sport.Intro.Title"] = "Introduction",
        ["Portfolio.BeyondAcademics.Sport.Intro.Content"] = "Since my professional activity is not physical, I practice a lot of sports (~5/6 times a week) to expend energy and gain motivation and discipline.",
        ["Portfolio.BeyondAcademics.Sport.Activities.Title"] = "Activities",
        ["Portfolio.BeyondAcademics.Sport.Activity1.Title"] = "Running",
        ["Portfolio.BeyondAcademics.Sport.Activity1.Content"] = "I have been running since late 2024, with more than 4 sessions per week. I run to set goals and push myself out of my comfort zone. My next goal is the Paris Marathon on April 12, 2026. Since I started, I have followed several training programs perfectly, regardless of events affecting me (weather, lack of time/motivation, travel, etc.). This sport is the perfect illustration of my motivation, consistency, and discipline.",
        ["Portfolio.BeyondAcademics.Sport.Activity2.Title"] = "Table tennis",
        ["Portfolio.BeyondAcademics.Sport.Activity2.Content"] = "I have been playing table tennis at the AGCV club in Cossé-le-Vivien since 2016. I only participate in team competitions, where cohesion and listening skills are essential. I use this sport to challenge myself against stronger opponents, analyze and understand my mistakes. This activity is proof of my ability to work in a team and my resilience. I was also the community manager for the club on Instagram and Facebook.",

