        // Aspi Hotel Booking page
        ["Portfolio.AspiHotel.Title"] = "ASP .NET hotel room booking website",
        ["Portfolio.AspiHotel.Subtitle"] = "ASP.NET web project around a booking system",
        ["Portfolio.AspiHotel.Context.Title"] = "Context",
        ["Portfolio.AspiHotel.Context.Description"] = "This project was carried out at university during the 3rd year of the BUT Computer Science program, as part of C# courses. The module represented 31.5 hours (9 sessions of 3h30) with concrete deliverables: a Git repository, unit tests, a small ASP.NET Core Web API with a console or WPF client, and a technical document. We had to learn a significant part of the content through self-learning to move forward efficiently. Learning goals included setting up a .NET environment, writing robust C# code (collections, LINQ), creating xUnit tests and basic integration tooling, exposing and documenting a Web API, and applying Git best practices (atomic commits, PRs, reviews). We were very free to choose technologies, which allowed us to shape the architecture according to our preferences and functional needs.",
        ["Portfolio.AspiHotel.Realization.Title"] = "Implementation",
        ["Portfolio.AspiHotel.Realization.Navigation.Title"] = "Navigation diagram",
        ["Portfolio.AspiHotel.Realization.Navigation.Description"] = "This navigation diagram shows the overall user journey in the hotel booking application. From the home page, users can access experiences, contact, login, and rooms (including featured rooms). After authentication, they can manage their profile (profile update and password change), view room details, make a booking, and confirm the action. The flow also includes management of existing bookings through the “My bookings” area, with detailed view and deletion options. This design step helped us validate navigation logic before implementation and ensured a clear, smooth user experience.",
        ["Portfolio.AspiHotel.Realization.Navigation.ImageAlt"] = "Application navigation diagram",
        ["Portfolio.AspiHotel.Realization.Figma.Title"] = "Figma mockups",
        ["Portfolio.AspiHotel.Realization.Figma.Description"] = "We started by designing Figma mockups to define the user journey and visual identity of the website. This step allowed us to quickly validate key screens (home, search, hotel details, booking) before implementing the frontend.",
        ["Portfolio.AspiHotel.Realization.Figma.Carousel.Image1Alt"] = "Home page",
        ["Portfolio.AspiHotel.Realization.Figma.Carousel.Image1Caption"] = "Figma mockup of the home page",
        ["Portfolio.AspiHotel.Realization.Figma.Carousel.Image2Alt"] = "Hotel preview",
        ["Portfolio.AspiHotel.Realization.Figma.Carousel.Image2Caption"] = "Figma mockup of the hotel preview on the home page",
        ["Portfolio.AspiHotel.Realization.Figma.Carousel.Image3Alt"] = "Hotel commitments",
        ["Portfolio.AspiHotel.Realization.Figma.Carousel.Image3Caption"] = "Figma mockup of the hotel commitments section and the footer",
        ["Portfolio.AspiHotel.Realization.Figma.Carousel.Image4Alt"] = "Login page",
        ["Portfolio.AspiHotel.Realization.Figma.Carousel.Image4Caption"] = "Figma mockup of the login page",
        ["Portfolio.AspiHotel.Realization.Figma.Carousel.Image5Alt"] = "Room overview",
        ["Portfolio.AspiHotel.Realization.Figma.Carousel.Image5Caption"] = "Figma mockup of a room page",
        ["Portfolio.AspiHotel.Realization.Figma.Carousel.Image6Alt"] = "Room booking information",
        ["Portfolio.AspiHotel.Realization.Figma.Carousel.Image6Caption"] = "Figma mockup of the room booking page",
        ["Portfolio.AspiHotel.Realization.Figma.Carousel.Image7Alt"] = "Profile page with upcoming bookings",
        ["Portfolio.AspiHotel.Realization.Figma.Carousel.Image7Caption"] = "Figma mockup of the profile page",
        ["Portfolio.AspiHotel.Realization.Structure.Title"] = "Solution structure",
        ["Portfolio.AspiHotel.Realization.Structure.Description"] = "The solution was organized into separate layers to keep responsibilities clear: API for HTTP exposure, Application for use cases, Domain for business rules, Infrastructure for data access, and Web for the client. This structure improved teamwork, testability, and long-term maintainability while keeping the codebase readable.",
        ["Portfolio.AspiHotel.Realization.Structure.ImageAlt"] = "HotelBooking solution structure",
        ["Portfolio.AspiHotel.Realization.Database.Title"] = "Database (SSMS)",
        ["Portfolio.AspiHotel.Realization.Database.Description"] = "On the data side, we modeled the database in SQL Server (SSMS) with the entities required for a booking platform: hotels, rooms, users, roles, bookings, reviews, visits, images, cities, and discounts. This model covered the core business needs while keeping a solid foundation for queries and future improvements.",
        ["Portfolio.AspiHotel.Realization.Database.ImageAlt"] = "Screenshot of SQL Server project tables",
        ["Portfolio.AspiHotel.Realization.Git.Title"] = "Team Git workflow",
        ["Portfolio.AspiHotel.Realization.Git.Description"] = "There were 3 of us on the project, and we applied a clean Git workflow with atomic commits and intention-based branch names (feature, fix, chore). This allowed us to work in parallel, review code more easily, and reduce integration conflicts.",
        ["Portfolio.AspiHotel.Realization.Git.ImageAlt"] = "Git terminal screenshot with branch history",
        ["Portfolio.AspiHotel.Conclusion.Title"] = "Conclusion / Result",
        ["Portfolio.AspiHotel.Conclusion.Description"] = "This project helped me reach a concrete milestone in full application development. I can now design and deliver a structured solution with an ASP.NET Core API, a web client, a SQL Server database, and a layered architecture (Domain, Application, Infrastructure). I significantly improved my API design skills, booking workflow implementation, data modeling, and team collaboration with Git. Today, I am able to build end-to-end business features, from requirements analysis to production deployment.",
        ["Portfolio.AspiHotel.Conclusion.VisitSiteButton"] = "View production website",
        ["Portfolio.AspiHotel.Conclusion.VisitRepoButton"] = "View GitHub repository",

        // Scratch page
        ["Portfolio.Scratch.Title"] = "My Scratch games",
        ["Portfolio.Scratch.Subtitle"] = "Introduction to programming in middle school",
        ["Portfolio.Scratch.Intro.Title"] = "My beginnings",
        ["Portfolio.Scratch.Intro.Description"] = "Scratch is where my passion for software development started. Scratch is an educational block-based programming language (similar to Blueprint). We learned how to use it in technology class in middle school (around age 13). I didn’t stop at the classes—Scratch became my main hobby for a few years before I taught myself Java, HTML, and CSS the following year (around age 14). Here are my three most polished Scratch games (kept exactly as they were since middle school).",
        ["Portfolio.Scratch.PlayButton"] = "Play on Scratch",

        ["Portfolio.Scratch.Game1.Title"] = "Rod World",
        ["Portfolio.Scratch.Game1.Description"] = "Rod World was coded in technology class. Once the game starts, cast the fishing rod by pressing the spacebar. After a while, a loading bar will appear. At that moment, you must press the spacebar as fast and as many times as possible to fill the bar! The goal? Get as many upgrades as possible and collect the 30 different fish! Good luck!",
        ["Portfolio.Scratch.Game1.Image1Alt"] = "Rod World main screen",
