        ["Portfolio.Scratch.Game2.Title"] = "Games Duels",
        ["Portfolio.Scratch.Game2.Description"] = "Games Duels is a duel game with four mini-games. Press the \"Y\" key to start. Have fun!",
        ["Portfolio.Scratch.Game2.Image1Alt"] = "Game menu",
        ["Portfolio.Scratch.Game2.Image1Cap"] = "Main menu screen of the game",
        ["Portfolio.Scratch.Game2.Image2Alt"] = "Pong game",
